// Contact Form Handler
function setupContactForm() {
    const contactForm = document.getElementById('contactForm');
    if (!contactForm) return;
    
    contactForm.addEventListener('submit', function(e) {
        e.preventDefault();
        
        // Validate form
        if (!validateForm(this)) {
            showUserFriendlyError('Please fill in all required fields correctly.');
            return;
        }
        
        // Get form data
        const formData = new FormData(this);
        const data = Object.fromEntries(formData);
        
        // Show loading state
        const submitBtn = this.querySelector('.submit-btn');
        const btnText = submitBtn.querySelector('.btn-text');
        const btnLoader = submitBtn.querySelector('.btn-loader');
        
        submitBtn.classList.add('loading');
        btnText.style.display = 'none';
        btnLoader.style.display = 'block';
        
        // Simulate form submission
        setTimeout(() => {
            try {
                // This would be your actual API call
                // fetch('/api/contact', {
                //     method: 'POST',
                //     headers: { 'Content-Type': 'application/json' },
                //     body: JSON.stringify(data)
                // })
                // .then(response => response.json())
                // .then(result => {
                //     showUserFriendlyError('Message sent successfully!', 3000);
                //     contactForm.reset();
                // })
                // .catch(error => handleApiError(error, 'Contact Form'));
                
                // For demo purposes
                showUserFriendlyError('Message sent successfully! We\'ll get back to you soon.', 4000);
                contactForm.reset();
                
            } catch (error) {
                handleError('Contact Form Submission', error);
                showUserFriendlyError('Failed to send message. Please try again.');
            } finally {
                // Reset button state
                submitBtn.classList.remove('loading');
                btnText.style.display = 'block';
                btnLoader.style.display = 'none';
            }
        }, 2000);
    });
}

// Newsletter Form Handler
function setupNewsletterForm() {
    const newsletterForms = document.querySelectorAll('.newsletter-form');
    
    newsletterForms.forEach(form => {
        form.addEventListener('submit', function(e) {
            e.preventDefault();
            
            const emailInput = this.querySelector('input[type="email"]');
            const email = emailInput.value.trim();
            
            if (!email || !isValidEmail(email)) {
                showUserFriendlyError('Please enter a valid email address.');
                return;
            }
            
            // Show loading state
            const submitBtn = this.querySelector('button');
            const originalText = submitBtn.textContent;
            submitBtn.textContent = 'Subscribing...';
            submitBtn.disabled = true;
            
            // Simulate subscription
            setTimeout(() => {
                try {
                    showUserFriendlyError('Thank you for subscribing to our newsletter!', 3000);
                    emailInput.value = '';
                } catch (error) {
                    handleError('Newsletter Subscription', error);
                    showUserFriendlyError('Subscription failed. Please try again.');
                } finally {
                    submitBtn.textContent = originalText;
                    submitBtn.disabled = false;
                }
            }, 1500);
        });
    });
}

