// Mobile CTA Bar
function initializeMobileCTA() {
    if (window.innerWidth <= 768) {
        createMobileCTA();
    }
    
    window.addEventListener('resize', function() {
        if (window.innerWidth <= 768) {
            createMobileCTA();
        } else {
            removeMobileCTA();
        }
    });
}

function createMobileCTA() {
    // Remove existing if present
    const existingCTA = document.getElementById('mobileCTA');
    if (existingCTA) return;
    
    const mobileCTA = document.createElement('div');
    mobileCTA.id = 'mobileCTA';
    mobileCTA.className = 'mobile-cta-bar';
    mobileCTA.innerHTML = `
        <button class="cta-button call-cta" onclick="window.location.href='tel:+919198923230'">
            <i class="ion-ios-telephone"></i>
            <span>Call Now</span>
        </button>
        <button class="cta-button whatsapp-cta" onclick="window.open('https://wa.me/919198923230', '_blank')">
            <i class="ion-social-whatsapp"></i>
            <span>WhatsApp</span>
        </button>
    `;
    
    document.body.appendChild(mobileCTA);
}

function removeMobileCTA() {
    const mobileCTA = document.getElementById('mobileCTA');
    if (mobileCTA) {
        mobileCTA.remove();
    }
}

